            if sha256(data).hexdigest() != row["sha256"]:
                reject("E_HIA_ARTIFACT_CORRUPT", "artifact bytes no longer match their recorded digest")
        return data, decode_data(row["metadata"])

    def _get_json_reference(self, ref, *, kind=None, _connection=None):
        data, metadata = self.get(ref, kind=kind, **_connection_arguments(_connection))
        return decode_data(data), metadata

    def _resolve_uri_reference(self, uri):
        row = self.db.execute("SELECT * FROM artifacts WHERE uri=?", (uri,)).fetchone()
        if row is None:
            reject("E_HIA_ARTIFACT_IDENTITY", "resource URI was not issued in this runtime namespace")
        ref = self._ref(row)
        self.get(ref)
        return ref

    def _profile_reference(self, identifier, value):
        ref = self.json(value, "profile")
        profile = {"id": identifier, "sha256": ref["sha256"]}
        self.db.execute("INSERT OR IGNORE INTO profiles VALUES (?,?,?)",
                        (identifier, ref["sha256"], wire(ref).decode()))
        return profile, ref

    def _check_profile_reference(self, ref, expected, *, _connection=None):
        if ref != expected:
            reject("E_HIA_PROFILE_STALE", "profile is unavailable or differs from the installed implementation")
        row = (self.db if _connection is None else _connection).execute("SELECT artifact FROM profiles WHERE id=? AND sha256=?",
                              (ref["id"], ref["sha256"])).fetchone()
        if row is None:
            reject("E_HIA_PROFILE_AUTHORITY", "profile does not resolve to a retained server record")
        return self.get_json(decode_data(row["artifact"]), kind="profile", **_connection_arguments(_connection))[0]

"""Observe exact pre/post-admission global binding against the retained body.

This first probe runs the original authored candidate unchanged. Differences
are actual failures, never expected-failure decorations or a qualification.
"""
from __future__ import annotations
import argparse
from hashlib import sha256
import json
from pathlib import Path
import sys
import traceback


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--source',type=Path,required=True)
    parser.add_argument('--manifest',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True)
    args=parser.parse_args()
    args.source=args.source.resolve(strict=True)
    args.output.mkdir(mode=0o700)
    sys.path.insert(0,str(args.source))
    from hepta import hia_agent_service as api
    from hepta import hia_service_evaluation_native as native
    from tests import hia_service_evaluation_fixtures as fixtures
    manifest_raw=args.manifest.read_bytes()
    manifest=json.loads(manifest_raw)
    image_path=args.manifest.parent/manifest['image_path']
    image_raw=image_path.read_bytes()
    assert sha256(image_raw).hexdigest()==manifest['image_sha256']
    anchors={name:vars(api)[name] for name in ('_connection_arguments','_value_observation')}
    records=[];held_images=[];current_error=None
    def observe(helper,kind,when,selected):
        events=[];image=None
        anchor=anchors[helper]
        def replacement(value):
            events.append(['call',helper])
            return anchor(value)
        class Foreign:
            def __getattribute__(self,name):
                if name=='__module__':
                    events.append(['metadata',name])
                    if kind=='object_metadata_error':
                        raise LookupError('metadata must not run during helper selection')
                    return 'foreign_evaluation_fixture'
                return object.__getattribute__(self,name)
            def __call__(self,value):
                events.append(['call',helper])
                return anchor(value)
        def mutate():
            if kind=='absent':
                del vars(api)[helper]
            elif kind=='original':
                vars(api)[helper]=anchor
            elif kind=='none':
                vars(api)[helper]=None
            elif kind=='function':
                vars(api)[helper]=replacement
            else:
                vars(api)[helper]=Foreign()
        try:
            if when=='pre':
                mutate()
            if selected:
                try:
                    image=native.NativeEvaluationImage(image_raw,manifest['image_sha256'])
                except BaseException as error:
                    return {'admission_events':list(events),'admission_error':{
                        'type':type(error).__name__,'args':list(error.args)},
                        'business':None,'helper_events':[],'actual_entries':0}
                held_images.append(image)
            admission_events=list(events);events.clear()
            if when=='post':
                mutate()
            before=0 if image is None else image.entries
            business=fixtures.fixture_call('eval-ok',image)
            return {'admission_events':admission_events,'admission_error':None,
                    'business':business,'helper_events':list(events),
                    'actual_entries':0 if image is None else image.entries-before}
        finally:
            vars(api)[helper]=anchor
    try:
        for helper in anchors:
            for when in ('pre','post'):
                for kind in ('original','function','none','object','absent','object_metadata_error'):
                    expected=observe(helper,kind,when,False)
                    actual=observe(helper,kind,when,True)
                    comparable={key:actual[key] for key in expected if key!='actual_entries'}
                    reference={key:expected[key] for key in expected if key!='actual_entries'}
                    reached=(actual['actual_entries']>0 or actual['admission_error'] is not None)
                    records.append({'helper':helper,'timing':when,'kind':kind,'reference':expected,
                                    'native':actual,'equal':comparable==reference,'native_observed':reached})
    except BaseException:
        current_error=traceback.format_exc()
    finally:
        for name,anchor in anchors.items():
            assert vars(api).get(name) is anchor
        stable=args.manifest.read_bytes()==manifest_raw and image_path.read_bytes()==image_raw
        passed=(len(records)==24 and current_error is None and stable
                and all(row['equal'] and row['native_observed'] for row in records))
        report={'schema':'hia.evaluation.pre-post-helper-binding.v1','status':'PASS' if passed else 'FAIL',
                'python':sys.version,'cases':records,'case_count':len(records),
                'equal_count':sum(row['equal'] for row in records),
                'source':{'runtime':sha256((args.source/'hepta/hia_service_evaluation_native.py').read_bytes()).hexdigest(),
                          'service':sha256((args.source/'hepta/hia_agent_service.py').read_bytes()).hexdigest()},
                'image_sha256':manifest['image_sha256'],'manifest_sha256':sha256(manifest_raw).hexdigest(),
                'input_bytes_unchanged':stable,'exception':current_error,
                'historical_results_transferred':False,'current_cold':False}
        raw=(json.dumps(report,sort_keys=True,indent=2,allow_nan=False)+'\n').encode()
        (args.output/'REPORT.json').write_bytes(raw)
        print(json.dumps({'status':report['status'],'cases':len(records),
              'equal':report['equal_count'],'report_sha256':sha256(raw).hexdigest()}),flush=True)
    return int(not passed)
if __name__=='__main__':raise SystemExit(main())

"""Exact Evaluation/import policies with held real IMPORT_FROM errors."""
from __future__ import annotations
import argparse
import builtins
from contextlib import ExitStack
from hashlib import sha256
import json
from pathlib import Path
import sys
from unittest.mock import patch
import weakref


def observe(fixtures, image, family, module_name, missing, outer):
    ports=fixtures.Ports('eval-ok' if family=='_hia_evaluate' else 'invoke-ok',image)
    provider=fixtures.runner if module_name=='hia_agent_runner' else fixtures.buffers
    events=[];weak=[];held=[]
    class Module:
        __name__='hepta.evaluation_import_proxy'
        __file__='/virtual/evaluation-import-proxy.py'
        def __init__(self):weak.append(weakref.ref(self))
        def __getattr__(self,name):
            events.append(['field',name])
            if name==missing:raise AttributeError(name)
            return getattr(provider,name)
        def __del__(self):
            active=sys.exception()
            events.append(['module-del',None if active is None else type(active).__name__])
    original_import=builtins.__import__
    def hooked(name,globals=None,locals=None,fromlist=(),level=0):
        if name==module_name and level==1:
            events.append(['import',list(fromlist)])
            return Module()
        return original_import(name,globals,locals,fromlist,level)
    def invoke():
        try:
            value=ports.invoke_case()
            return {'kind':'value','value':fixtures.normalize(value)}
        except BaseException as error:
            held.append(error)
            context=error.__context__
            return {'kind':'error','type':type(error).__name__,'args':fixtures.normalize(error.args),
                'name':getattr(error,'name',None),'path':getattr(error,'path',None),
                'context':None if context is None else [type(context).__name__,fixtures.normalize(context.args)],
                'suppress_context':error.__suppress_context__}
    def run():
        value=invoke()
        before={'alive':[ref() is not None for ref in weak],'events':list(events)}
        held.clear()
        return {'result':value,'while_error_held':before,
            'after_error_release':{'alive':[ref() is not None for ref in weak],'events':list(events)},
            'business':fixtures.normalize(ports.events),'publications':fixtures.normalize(ports.store.published)}
    with ExitStack() as stack:
        stack.enter_context(patch.object(fixtures.api,'time',ports.clock))
        stack.enter_context(patch.object(fixtures.api,'validate',lambda *args,**kwargs:ports.events.append(['validate'])))
        stack.enter_context(patch.object(fixtures.runner,'run_reference_batch',ports.reference_batch))
        stack.enter_context(patch.object(fixtures.runner,'run_native_batch',ports.native_batch))
        stack.enter_context(patch.object(fixtures.buffers,'validate_cases',lambda *args:ports.events.append(['validate_cases'])))
        stack.enter_context(patch.object(fixtures.buffers,'validate_arguments',lambda *args:ports.events.append(['validate_arguments'])))
        stack.enter_context(patch.object(builtins,'__import__',hooked))
        if outer:
            try:raise LookupError('outer')
            except LookupError:return run()
        return run()


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--source',type=Path,required=True)
    parser.add_argument('--manifest',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True)
    args=parser.parse_args()
    sys.path.insert(0,str(args.source.resolve()))
    from tests import hia_service_evaluation_fixtures as fixtures
    from hepta.hia_service_evaluation_native import NativeEvaluationImage
    manifest_raw=args.manifest.read_bytes();manifest=json.loads(manifest_raw)
    image_path=args.manifest.parent/manifest['image_path'];image_raw=image_path.read_bytes()
    assert sha256(image_raw).hexdigest()==manifest['image_sha256']
    files=('hepta/hia_service_evaluation_native.py','hepta/hia_service_evaluation_foreign.py',
        'tools/generate_hia_service_evaluation_foreign.py','tools/hia_service_evaluation_policy.py')
    before={name:sha256((args.source/name).read_bytes()).hexdigest() for name in files}
    image=NativeEvaluationImage(image_raw,manifest['image_sha256'])
    rows=[]
    groups=(('_hia_evaluate','hia_agent_runner',(None,'run_native_batch','run_reference_batch')),
        ('_hia_evaluate','hia_agent_buffers',(None,'validate_cases')),
        ('invoke_lease','hia_agent_runner',(None,'run_native_batch')),
        ('invoke_lease','hia_agent_buffers',(None,'validate_arguments')))
    for family,module,names in groups:
        for name in names:
            for outer in (False,True):
                reference=observe(fixtures,None,family,module,name,outer)
                start=image.entries
                actual=observe(fixtures,image,family,module,name,outer)
                rows.append({'family':family,'module':module,'missing':name,'outer':outer,
                    'reference':reference,'native':actual,'equal':reference==actual,
                    'actual_entries':image.entries-start})
    after={name:sha256((args.source/name).read_bytes()).hexdigest() for name in files}
    report={'schema':'hia.evaluation.import-module-retirement.v1','python':sys.version,
        'cases':len(rows),'equal':sum(row['equal'] for row in rows),'observations':rows,
        'image_sha256':manifest['image_sha256'],'source_before':before,'source_after':after,
        'inputs_unchanged':before==after and args.manifest.read_bytes()==manifest_raw and image_path.read_bytes()==image_raw,
        'whole_native':False,'current_cold':False,'garbage_collection_used':False}
    report['status']='PASS' if (report['equal']==report['cases'] and report['inputs_unchanged']
        and all(row['actual_entries']>0 for row in rows)) else 'FAIL'
    args.output.mkdir(mode=0o700)
    (args.output/'REPORT.json').write_text(json.dumps(report,sort_keys=True,indent=2)+'\n')
    print(json.dumps({k:report[k] for k in ('status','cases','equal','inputs_unchanged')}))
    return report['status']!='PASS'


if __name__=='__main__':raise SystemExit(main())

